#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define all() a.begin() + 1,a.begin() + n + 1int T,n; const int mod = 998244353;const int N = 55; int fac[N],invfac[N]; int qpow(int a,int b){    int r = 1;    while(b){        if(b & 1)r = r * a % mod;        a = a * a % mod;        b >>= 1;    }    return r;} int C(int n,int m){    if(m < 0 || m > n)return 0;    return fac[n] * invfac[m] % mod * invfac[n - m] % mod;} void O_o(){    cin >> n;    vector<int> a(n + 1);    int sum = 0;    for(int i = 0;i <= n;i++){        cin >> a[i];        sum += a[i];    }     int q = sum / n,r = sum % n;    int cnt_big = 0,cnt_small = 0;     for(int i = 1;i <= n;i++){        if(a[i] > q + 1){            cout << 0 << '\n';            return;        }        if(a[i] == q + 1)cnt_big++;        else cnt_small++;    }     if(cnt_big > r){        cout << 0 << '\n';        return;    }     int ans = C(cnt_small,r - cnt_big);    ans = ans * fac[r] % mod;    ans = ans * fac[n - r] % mod;    cout << ans << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);     fac[0] = 1;    for(int i = 1;i < N;i++)fac[i] = fac[i - 1] * i % mod;    invfac[N - 1] = qpow(fac[N - 1],mod - 2);    for(int i = N - 2;i >= 0;i--)invfac[i] = invfac[i + 1] * (i + 1) % mod;     cin >> T;    while(T--)O_o();}